                     for x in CONTROL_X)
    return {
        "board": [row[:] for row in board],
        "selected": selected,
        # Initially blue cells are defects; all other cells start correct.
        "wrong": [[board[y][x] == 11 for x in range(14, 51)]
                  for y in range(9, 41)],
        "moves": 0,
    }


def _draw_counter(state):
